<?php
namespace App\Http\Controllers;
use App\Models\{Exam,Attempt,Answer}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class AttemptController extends Controller { public function start(Exam $exam){abort_unless(auth()->user()->isStudent(),403);abort_unless($exam->isOpen(),403,'This examination is not available.');abort_if($exam->questions()->count()<1,422,'This examination has no questions.');$existing=Attempt::where('exam_id',$exam->id)->where('user_id',auth()->id())->where('status','in_progress')->first();if($existing)return redirect()->route('attempts.show',$existing);$attempt=Attempt::create(['exam_id'=>$exam->id,'user_id'=>auth()->id(),'started_at'=>now(),'status'=>'in_progress','total_points'=>$exam->questions()->sum('points')]);return redirect()->route('attempts.show',$attempt);} public function show(Attempt $attempt){abort_unless($attempt->user_id===auth()->id(),403);abort_unless($attempt->isActive(),403,'Attempt already submitted.');$attempt->load('exam.questions.options');$deadline=$attempt->started_at->copy()->addMinutes($attempt->exam->duration_minutes);if(now()->gte($deadline))return $this->finish($attempt,[]);return view('attempts.show',compact('attempt','deadline'));} public function save(Request $r,Attempt $attempt){abort_unless($attempt->user_id===auth()->id()&&$attempt->isActive(),403);$data=$r->validate(['answers'=>'nullable|array']);return $this->finish($attempt,$data['answers']??[]);} private function finish(Attempt $attempt,array $answers){return DB::transaction(function()use($attempt,$answers){$exam=$attempt->exam->load('questions.options');$score=0;foreach($exam->questions as $q){$optionId=$answers[$q->id]??null;$option=$optionId?$q->options->firstWhere('id',(int)$optionId):null;$correct=(bool)optional($option)->is_correct;$points=$correct?(float)$q->points:0;$attempt->answers()->updateOrCreate(['question_id'=>$q->id],['option_id'=>$option?->id,'is_correct'=>$correct,'points_awarded'=>$points]);$score+=$points;}$attempt->update(['score'=>$score,'submitted_at'=>now(),'status'=>'submitted']);return redirect()->route('results.show',$attempt)->with('success','Exam submitted successfully.');});} }
